// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(depositAmount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 0, 1e30);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        bool depositOk; try c.Deposit{value: depositAmount}() { depositOk = true; } catch { depositOk = false; }
        depositOk;

        uint256 balBefore = c.balances(actor);
        uint256 contractBalBefore = address(c).balance;

        vm.prank(actor);
        bool witOk; try c.CashOut{value: 0}(withdrawAmount) { witOk = true; } catch { witOk = false; }

        if (witOk && withdrawAmount <= balBefore) {
            assertTrue(
                c.balances(actor) == balBefore - withdrawAmount &&
                address(c).balance == contractBalBefore - withdrawAmount
            );
        } else {
            assertTrue(
                c.balances(actor) == balBefore &&
                address(c).balance == contractBalBefore
            );
        }
    }
}
